// 1. Create a hash map to store numbers and their indices
// 2. Loop through the array
// 3. For each number, calculate complement = target - current number
// 4. Check if complement exists in hash map
// 5. If yes, return [complement_index, current_index]
// 6. If no, store current number and index in hash map

function twoSum(nums, target) {
    const map = new Map();
    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];
        if (map.has(complement)) {
            return [map.get(complement), i];
        }
        map.set(nums[i], i);
    }
    return [];
}

