//    - Swap s[left] with s[right]
//    - Increment left, decrement right
// 3. String is reversed in-place

function reverseString(s) {
    let left = 0;
    let right = s.length - 1;
    while (left < right) {
        [s[left], s[right]] = [s[right], s[left]];
        left++;
        right--;
    }
}

