// PSEUDO CODE:
// 1. Create a dummy head node
// 2. Use two pointers for both lists
// 3. Compare current nodes, append smaller one to result
// 4. Move pointer of the list from which node was taken
// 5. Continue until one list is exhausted
// 6. Append remaining nodes from the other list

function mergeTwoLists(list1, list2) {
    const dummy = { val: 0, next: null };
    let current = dummy;

    while (list1 !== null && list2 !== null) {
        if (list1.val <= list2.val) {
            current.next = list1;
            list1 = list1.next;
        } else {
            current.next = list2;
            list2 = list2.next;
        }
        current = current.next;
    }

    current.next = list1 !== null ? list1 : list2;
    return dummy.next;
}

