// PSEUDO CODE:
// 1. Use two queues: mainQueue and helperQueue
// 2. For push: Add to mainQueue, then move all elements from mainQueue to helperQueue, then swap
// 3. For pop: Remove from front of mainQueue
// 4. For top: Return front of mainQueue
// 5. For empty: Check if mainQueue is empty

class MyStack {
    constructor() {
        this.mainQueue = [];
        this.helperQueue = [];
    }

    push(x) {
        this.mainQueue.push(x);
        while (this.helperQueue.length > 0) {
            this.mainQueue.push(this.helperQueue.shift());
        }
        [this.mainQueue, this.helperQueue] = [this.helperQueue, this.mainQueue];
    }

    pop() {
        return this.helperQueue.shift();
    }

    top() {
        return this.helperQueue[0];
    }

    empty() {
        return this.helperQueue.length === 0;
    }
}

