// PSEUDO CODE:
// 1. Use two stacks: one for values, one for minimums
// 2. For push: Push to value stack, push min(current min, val) to min stack
// 3. For pop: Pop both stacks
// 4. For top: Return top of value stack
// 5. For getMin: Return top of min stack

class MinStack {
    constructor() {
        this.stack = [];
        this.minStack = [];
    }

    push(val) {
        this.stack.push(val);
        const minVal = this.minStack.length === 0 ? val : Math.min(this.minStack[this.minStack.length - 1], val);
        this.minStack.push(minVal);
    }

    pop() {
        this.stack.pop();
        this.minStack.pop();
    }

    top() {
        return this.stack[this.stack.length - 1];
    }

    getMin() {
        return this.minStack[this.minStack.length - 1];
    }
}

